// app.module.ts
import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { AppComponent } from './app.component';
import { SharedComponent } from './components/shared.component';

@NgModule({
  declarations: [AppComponent, SharedComponent],
  imports: [BrowserModule],
  providers: [],
  bootstrap: [AppComponent]
})
export class AppModule {}
```
3. **Reuse the component**: Once the component is registered, you can reuse it across multiple modules by importing it and including it in the `declarations` array of the respective modules.

For example, let's say you have a separate module called `foo.module.ts` and you want to use the shared component there:
```typescript
