  imports: [BrowserModule],
  providers: [],
  exports: [FooComponent]
})
export class FooModule {}
```
**Note**: The above example assumes that the shared component is located in the same directory as the `app.module.ts` file. If your shared component is located in a different directory, you may need to adjust the import path accordingly.

4. **Use the component**: Finally, you can use the shared component in your `foo.component.html` file like any other component:
```html
