const predictionsDiv = document.getElementById('predictions');

searchInput.addEventListener('input', async () => {
  const searchQuery = searchInput.value.trim();
  if (searchQuery.length > 2) {
    const apiUrl = 'https://www.googleapis.com/customsearch/v1';
    const apiKey = 'YOUR_API_KEY';
    const cseId = 'YOUR_CSE_ID';
    const parameters = {
      key: apiKey,
      cx: cseId,
      q: searchQuery,
    };

    try {
      const response = await fetch(apiUrl, { params: parameters });
      const predictions = await response.json();

      predictionsDiv.innerHTML = '';
      predictions.items.forEach((prediction) => {
        const predictionHtml = `
          <div>
            <a href="${prediction.link}">${prediction.title}</a>
          </div>
        `;
        predictionsDiv.innerHTML += predictionHtml;
      });
    } catch (error) {
      console.error('Error fetching predictions:', error);
    }
  }
});
```
Replace `YOUR_API_KEY` and `YOUR_CSE_ID` with your actual Google Custom Search API credentials.

